<template><div class="app-container"><el-tabs v-model="statusTab" @tab-change="search"><el-tab-pane label="全部询盘" name="all"/><el-tab-pane label="待处理" name="NEW"/><el-tab-pane label="已处理" name="DONE"/><el-tab-pane label="垃圾留言" name="SPAM"/></el-tabs><el-form inline @submit.prevent="search"><el-form-item label="跟进"><el-select v-model="q.due" clearable style="width:140px"><el-option label="今日需跟进" value="today"/><el-option label="已逾期" value="overdue"/><el-option label="已安排" value="scheduled"/></el-select></el-form-item><el-form-item label="提交日期"><el-date-picker v-model="q.from" type="date" value-format="YYYY-MM-DD" placeholder="开始" style="width:145px"/><span> 至 </span><el-date-picker v-model="q.to" type="date" value-format="YYYY-MM-DD" placeholder="结束" style="width:145px"/></el-form-item><el-form-item v-if="canAssign" label="负责人ID"><el-input-number v-model="q.ownerUserId" :min="0" :precision="0" placeholder="全部" controls-position="right"/></el-form-item><el-form-item><el-checkbox v-model="q.mine">分配给我</el-checkbox></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button><InquiryExport :filter="q"/></el-form-item></el-form>
<el-alert title="个人无需指派即可处理；若开启负责人隔离，普通账号只看自己的询盘。列表联系方式遮蔽；清除会同时擦除跟进文字，备份另按保留策略管理。" :closable="false"/>
<el-table :data="rows" v-loading="loading"><el-table-column prop="inquiryId" label="编号" width="80"/><el-table-column prop="name" label="称呼"/><el-table-column prop="contact" label="联系方式（遮蔽）"/><el-table-column label="状态" width="100"><template #default="s">{{labels[s.row.status]}}</template></el-table-column><el-table-column prop="ownerName" label="负责人"/><el-table-column prop="nextFollowAt" label="下次跟进（北京）" width="170"/><el-table-column prop="createTime" label="提交时间" width="170"/><el-table-column label="操作" min-width="180"><template #default="s"><el-button v-hasPermi="['cms:inquiry:query']" link type="primary" @click="detail(s.row.inquiryId)">详情与跟进</el-button><el-button v-hasPermi="['cms:inquiry:remove']" link type="danger" @click="erase(s.row)">清除</el-button></template></el-table-column></el-table><pagination v-if="total" :total="total" v-model:page="q.pageNum" v-model:limit="q.pageSize" @pagination="load"/>
<el-dialog v-model="visible" title="询盘详情与跟进" width="min(900px,calc(100vw - 32px))" append-to-body destroy-on-close @closed="clear">
 <el-tabs v-if="row" v-model="detailTab" @tab-change="v=>v==='history'&&loadRecords()"><el-tab-pane label="留言与处理" name="detail"><el-form label-width="100px" :disabled="busy"><el-form-item label="称呼">{{row.name}}</el-form-item><el-form-item label="联系方式">{{row.contact}}</el-form-item><el-form-item label="留言"><div class="plain">{{row.message}}</div></el-form-item><el-form-item label="状态"><el-select v-model="row.status" :disabled="!canEdit"><el-option v-for="(v,k) in labels" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="处理备注"><el-input v-model="row.note" :disabled="!canEdit" type="textarea" maxlength="500"/></el-form-item><el-form-item v-if="canEdit"><el-button type="primary" :loading="busy" @click="save">保存状态与备注</el-button></el-form-item>
 </el-form></el-tab-pane><el-tab-pane label="指派与跟进" name="follow"><el-form label-width="100px" :disabled="busy"><el-form-item label="负责人"><span>#{{team?.ownerUserId||'未分配'}}</span><template v-if="canAssign"><WorkflowPersonPicker v-model="owner"/><el-button :loading="busy" @click="assign">保存指派</el-button></template></el-form-item><el-divider>新增跟进</el-divider><p>当前下次跟进：{{team?.nextFollowAt||'未安排'}}。填写时间会替换原提醒；留空即取消。仅待处理状态可安排。</p><el-form-item label="跟进记录"><el-input v-model="follow.text" :disabled="!canEdit" type="textarea" maxlength="2000" placeholder="本次沟通情况"/></el-form-item><el-form-item label="处理结果"><el-input v-model="follow.result" :disabled="!canEdit" maxlength="200" placeholder="例如：已发送资料，等待客户回复"/></el-form-item><el-form-item label="下次跟进"><el-date-picker v-model="follow.nextFollowAt" :disabled="!canEdit||row.status!=='NEW'" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="北京时间，可不安排" clearable/></el-form-item><el-form-item v-if="canEdit"><el-button type="primary" :loading="busy" @click="append">记录本次跟进</el-button></el-form-item></el-form></el-tab-pane><el-tab-pane label="跟进记录" name="history"><el-divider>跟进时间线</el-divider><el-table :data="records"><el-table-column prop="createTime" label="时间" width="170"/><el-table-column prop="createBy" label="记录人" width="110"/><el-table-column prop="text" label="记录" min-width="200"/><el-table-column prop="result" label="结果/指派" min-width="160"/></el-table><pagination v-if="recordTotal" :total="recordTotal" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="loadRecords"/></el-tab-pane></el-tabs><template #footer><el-button @click="visible=false">关闭</el-button></template>
</el-dialog></div></template>
<script setup>
import{ref,computed,reactive,onMounted,onBeforeUnmount,onDeactivated,onActivated,watch}from'vue';import{useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{workflow}from'@/api/cms/workflow';import auth from '@/plugins/auth';import WorkflowPersonPicker from '../components/WorkflowPersonPicker.vue'
import InquiryExport from '../components/InquiryExport.vue'
const route=useRoute(),detailTab=ref('detail'),rows=ref([]),row=ref(),team=ref(),total=ref(0),loading=ref(false),busy=ref(false),visible=ref(false),owner=ref(0),records=ref([]),recordTotal=ref(0),q=reactive({status:'',due:'',mine:false,from:'',to:'',ownerUserId:undefined,pageNum:1,pageSize:10}),pg=reactive({pageNum:1,pageSize:10}),follow=reactive({text:'',result:'',nextFollowAt:''}),labels={NEW:'待处理',DONE:'已处理',SPAM:'垃圾留言'},canAssign=auth.hasPermi('cms:inquiry:assign'),canEdit=auth.hasPermi('cms:inquiry:edit');let epoch=0,details=0
const statusTab=computed({get:()=>q.status||'all',set:v=>q.status=v==='all'?'':v})
async function load(){const n=++epoch;loading.value=true;try{const r=await workflow('inquiry/tasks','get',undefined,{...q});if(n===epoch){rows.value=r.rows;total.value=r.total}}finally{if(n===epoch)loading.value=false}}function search(){q.pageNum=1;load()}function reset(){Object.assign(q,{status:'',due:'',mine:false,from:'',to:'',ownerUserId:undefined,pageNum:1});load()}
async function detail(id,keepTab=false){if(!keepTab)detailTab.value='detail';const n=++details;const [r,t]=await Promise.all([workflow('inquiry/'+id),workflow(`inquiry/${id}/team`)]);if(n!==details)return;row.value=r.data;team.value=t.data;owner.value=t.data.ownerUserId;visible.value=true;pg.pageNum=1;Object.assign(follow,{text:'',result:'',nextFollowAt:t.data.nextFollowAt||''});if(detailTab.value==='history')await loadRecords()}
async function loadRecords(){if(!row.value)return;const n=details,r=await workflow(`inquiry/${row.value.inquiryId}/followups`,'get',undefined,{...pg});if(n===details){records.value=r.rows;recordTotal.value=r.total}}
async function action(path,data){if(busy.value||!row.value)return;busy.value=true;const id=row.value.inquiryId,n=details;try{await workflow(`inquiry/${id}${path}`,path?'post':'put',data);if(n!==details)return;ElMessage.success('已保存');await detail(id,true);await load()}finally{busy.value=false}}
function save(){action('',{version:row.value.version,status:row.value.status,note:row.value.note})}function assign(){action('/assign',{version:row.value.version,ownerUserId:owner.value})}function append(){if(!follow.text.trim()){ElMessage.warning('请填写跟进记录');return};action('/followups',{version:row.value.version,...follow})}
async function erase(v){try{await ElMessageBox.confirm('永久擦除该询盘的联系人、正文、备注与跟进文字，并取消提醒？','清除询盘',{type:'warning'});await workflow('inquiry/'+v.inquiryId,'delete',{version:v.version});await load()}catch{}}
function clear(){++details;row.value=null;team.value=null;records.value=[];recordTotal.value=0;Object.assign(follow,{text:'',result:'',nextFollowAt:''})}function close(){++epoch;visible.value=false;clear()}
function routeOpen(){if(route.path!=='/cms/inquiry')return;const id=Number(route.query.inquiryId);if(Number.isSafeInteger(id)&&id>0)detail(id)}watch(()=>route.query.inquiryId,routeOpen);onMounted(()=>{if(route.query.due)q.due=String(route.query.due);load();routeOpen()});onBeforeUnmount(close);let resumed=false;onDeactivated(()=>{resumed=true;close()});onActivated(()=>{if(resumed){resumed=false;load();routeOpen()}})
</script><style scoped>.plain{white-space:pre-wrap;overflow-wrap:anywhere}</style>
